#!/usr/bin/env bash
set -Eeuo pipefail
export LANG=C.UTF-8
export LC_ALL=C.UTF-8
export LC_CTYPE=C.UTF-8

# FLIGHTCORE_PUBLIC_INSTALLER_4_2_2_RC14_FACTORY_V42
# SIYI_RUNTIME_STATE_NAMESPACE_MIGRATION_V2
# SIYI_VIDEO_SOURCE_PREVIOUS_STATE_FIX_V1
# SIYI_PUBLIC_INSTALLER_STABLE_CWD_V1
# SIYI_PARAM_IMPORT_STORAGE_PREFLIGHT_V2
# approved_original_source_server_sha256=04b56b8399039b4194098e1b24af7afb223ffbf39533cd7324db0b70b8ce08b0
# approved_legacy_bootstrap_server_sha256=de2373f641690220d75ace4909dce4160cc641655a0554b42c76bd90925051d8
# approved_v3_bootstrap_source_server_sha256=9bbb4e8718022ab99c9aaf50f711d10374f1bdfff4dd129dfdd40f27eeb38421
# approved_bootstrap_source_server_sha256=43c3d47d230e7f49d961a66180cdbaa3ee38bcf8c18c84312df8396f2e441e55
RAW_BASE="https://raw.githubusercontent.com/johbaa/SIYI_PI_Installer/main"
MANIFEST_URL="$RAW_BASE/manifest.json"
WORK_DIR="/home/pi/siyi-github-install"
BOOTSTRAP_DIR="/tmp/siyi-source-ui-bootstrap-v5"
mkdir -p "$WORK_DIR"
rm -rf "$BOOTSTRAP_DIR"
mkdir -p "$BOOTSTRAP_DIR"

# Normalize configured 4.2.0 runtime state and patch its WebUI before target download. Fresh installs are a strict no-op.
printf '%s' '' | base64 -d > "$BOOTSTRAP_DIR/patch_webui_upgrader_ux_v2.py"
printf '%s' '' | base64 -d > "$BOOTSTRAP_DIR/patch_webui_upgrader_ux_v3.py"
printf '%s' '' | base64 -d > "$BOOTSTRAP_DIR/patch_webui_upgrader_ux_v4.py"
printf '%s' '' | base64 -d > "$BOOTSTRAP_DIR/source_ui_bootstrap_runtime_v5.py"
chmod 600 "$BOOTSTRAP_DIR"/*.py
PYTHONPATH="$BOOTSTRAP_DIR" python3 "$BOOTSTRAP_DIR/source_ui_bootstrap_runtime_v5.py"

: > /tmp/siyi_webui_update.log 2>/dev/null || true
cd "$WORK_DIR"
curl -fsSL --silent --show-error --connect-timeout 10 --max-time 30 -o manifest.json "$MANIFEST_URL"
VERSION="$(python3 - <<'PYVERSION'
import json,re
with open('manifest.json',encoding='utf-8') as f:
    value=str(json.load(f).get('stable','')).strip()
if not re.fullmatch(r'[0-9]+\.[0-9]+\.[0-9]+',value):
    raise SystemExit('manifest stable version is missing or invalid')
print(value)
PYVERSION
)"
ARCHIVE="SIYI_RPI_INSTALLER_RELEASE_${VERSION}.tar.gz"
CHECKSUM="SIYI_RPI_INSTALLER_RELEASE_${VERSION}.sha256"
DIR="SIYI_RPI_INSTALLER_RELEASE_${VERSION}"

curl -fsSL --silent --show-error --connect-timeout 10 --max-time 900 -o "$ARCHIVE" "$RAW_BASE/$ARCHIVE"
curl -fsSL --silent --show-error --connect-timeout 10 --max-time 30 -o "$CHECKSUM" "$RAW_BASE/$CHECKSUM"
EXPECTED="$(awk 'NR==1 {print $1}' "$CHECKSUM")"
ACTUAL="$(sha256sum "$ARCHIVE" | awk '{print $1}')"
[[ "$EXPECTED" =~ ^[0-9a-fA-F]{64}$ ]] || { echo "Invalid published SHA256 file" >&2; exit 1; }
[ "${EXPECTED,,}" = "${ACTUAL,,}" ] || { echo "SHA256 verification failed" >&2; exit 1; }
rm -rf "$DIR"
tar -xzf "$ARCHIVE"
INSTALLER_DIR="$WORK_DIR/$DIR"
[ -f "$INSTALLER_DIR/install.sh" ] || { echo "Extracted installer is missing" >&2; exit 1; }
chmod +x "$INSTALLER_DIR/install.sh"
# The target installer snapshots itself into /run. Keep this launcher in a
# stable cwd as well, because managed-extra cleanup removes WORK_DIR.
cd /
bash "$INSTALLER_DIR/install.sh" "$@"
